INSERT INTO resources (title, type, category, url, body) VALUES
  ('Box breathing in four steps', 'article', 'Stress', NULL,
   'Breathe in for 4 seconds, hold for 4, breathe out for 4, hold for 4. Repeat for two minutes. Slowing your breathing tells your body it is safe, which lowers your heart rate. You can try it on the Breathe page.'),
  ('Why sleep matters before exams', 'article', 'Sleep', NULL,
   'Memory is consolidated during sleep. Pulling an all-nighter often costs more marks than it gains. Aim for 7 to 8 hours, keep your phone away from the bed and stop studying 30 minutes before sleeping.'),
  ('The 5-4-3-2-1 grounding exercise', 'article', 'Anxiety', NULL,
   'When anxiety rises, name 5 things you can see, 4 you can touch, 3 you can hear, 2 you can smell and 1 you can taste. It pulls your attention back to the present moment.'),
  ('Studying without burning out', 'article', 'Students', NULL,
   'Study in blocks of 25 to 45 minutes with short breaks. Plan the day the night before, keep one evening a week free, and remember that rest is part of studying, not time taken away from it.'),
  ('Five minutes of mindfulness', 'article', 'Mindfulness', NULL,
   'Sit comfortably and notice your breath without changing it. When your mind wanders, gently bring it back. Doing this for five minutes a day makes it easier to step back from worries.'),
  ('Tele-MANAS: free mental health support', 'link', 'Students', 'https://telemanas.mohfw.gov.in', NULL),
  ('WHO: mental health facts', 'link', 'Stress', 'https://www.who.int/news-room/fact-sheets/detail/mental-health-strengthening-our-response', NULL),
  ('NIMH: anxiety disorders explained', 'link', 'Anxiety', 'https://www.nimh.nih.gov/health/topics/anxiety-disorders', NULL),
  ('5-minute body scan meditation', 'video', 'Mindfulness', 'https://www.youtube.com/results?search_query=5+minute+body+scan+meditation', NULL),
  ('How to ride out a panic attack', 'article', 'Anxiety', NULL,
   'A panic attack feels frightening, but it is not dangerous and usually peaks within about 10 minutes. Don''t fight it. Breathe out slowly, a little longer than you breathe in, and remind yourself that it will pass. Afterwards, be gentle with yourself and rest.'),
  ('Set a daily worry time', 'article', 'Stress', NULL,
   'Pick 15 minutes at the same time each day as your worry time. When a worry comes up during the day, write it down and save it for later. In your worry time, read the list and decide what you can act on. Many worries feel smaller by then.'),
  ('Can''t sleep? Try the 20-minute rule', 'article', 'Sleep', NULL,
   'If you have been lying awake for about 20 minutes, get up and do something calm in dim light, like reading a paper book. Go back to bed when you feel sleepy. This teaches your brain that bed is for sleeping, not for lying awake worrying.'),
  ('Helping a friend who is struggling', 'article', 'Students', NULL,
   'Listen more than you talk, and don''t rush to fix things or judge. Tell them you are glad they told you. If you are worried about their safety, ask them directly whether they are thinking of hurting themselves. Asking does not put the idea in their head. Help them reach a helpline or a helper, and look after yourself too.'),
  ('Talking to your parents about how you feel', 'article', 'Students', NULL,
   'Choose a calm moment, not right after an argument. Start small with one feeling, using sentences like "I have been feeling stressed lately". Tell them what would help, such as just listening. If it doesn''t go well the first time, try again later or talk to another adult you trust.'),
  ('Dealing with results and comparison', 'article', 'Students', NULL,
   'Your marks measure one exam on one day, not your worth or your future. Around results, spend less time on social media and group chats where everyone compares scores. Talk to one person you trust about how you feel, and remember that there are many paths to a good life.'),
  ('Mindful walking', 'article', 'Mindfulness', NULL,
   'Walk slowly for five minutes, indoors or outside. Notice each foot touching the ground, the sounds around you and the air on your skin. When your mind wanders, bring it back to your steps. It is a good option if sitting still to meditate feels hard.'),
  ('iCall: free counselling by TISS', 'link', 'Students', 'https://icallhelpline.org',
   'Free counselling from trained counsellors at the Tata Institute of Social Sciences. Call 9152987821.'),
  ('Vandrevala Foundation helpline', 'link', 'Stress', 'https://www.vandrevalafoundation.com',
   'Free mental health support from trained counsellors. Call +91 9999666555.'),
  ('Live Love Laugh Foundation', 'link', 'Students', 'https://www.thelivelovelaughfoundation.org',
   'An Indian foundation working to reduce the stigma around mental health, with guides and a directory of helplines.'),
  ('WHO: Doing What Matters in Times of Stress', 'link', 'Stress', 'https://www.who.int/publications/i/item/9789240003927',
   'A free illustrated guide from the World Health Organization with simple skills for coping with stress.'),
  ('NHS Every Mind Matters', 'link', 'Anxiety', 'https://www.nhs.uk/every-mind-matters/',
   'Practical self-help for anxiety, stress and low mood from the UK''s National Health Service.'),
  ('Sleep Foundation: sleep hygiene', 'link', 'Sleep', 'https://www.sleepfoundation.org/sleep-hygiene',
   'Everyday habits that help you fall asleep faster and sleep better.'),
  ('How to make stress your friend', 'video', 'Stress', 'https://www.ted.com/talks/kelly_mcgonigal_how_to_make_stress_your_friend',
   'TED talk by psychologist Kelly McGonigal on how the way you think about stress changes how your body reacts to it.'),
  ('Sleep is your superpower', 'video', 'Sleep', 'https://www.ted.com/talks/matt_walker_sleep_is_your_superpower',
   'TED talk by sleep scientist Matt Walker on what sleep does for memory, mood and health.'),
  ('How to cope with anxiety', 'video', 'Anxiety', 'https://www.ted.com/talks/olivia_remes_how_to_cope_with_anxiety',
   'TED talk by Cambridge researcher Olivia Remes with practical ways to manage anxiety.'),
  ('Why we all need to practice emotional first aid', 'video', 'Mindfulness', 'https://www.ted.com/talks/guy_winch_why_we_all_need_to_practice_emotional_first_aid',
   'TED talk by psychologist Guy Winch on looking after emotional hurts like failure, loneliness and rejection.');

INSERT INTO affirmations (text) VALUES
  ('You don''t have to have it all figured out today.'),
  ('Asking for help is a sign of strength.'),
  ('Small steps still move you forward.'),
  ('Your feelings are valid, even the messy ones.'),
  ('Rest is productive too.'),
  ('You have handled hard days before. You can handle this one.'),
  ('It''s okay to take things one breath at a time.');
